using System;
using System.IO;
using Aspose.Cells;

// The C# example uses Aspose.Cells to create a new empty workbook, saves it as a macro-enabled .xlsm file, and outputs the full file path. After the workbook is generated, developers can open the VBA editor and add a COM library reference such as Microsoft Scripting Runtime to the VBA project.
class Program
{
    static void Main()
    {
        try
        {
            // Create a new empty workbook
            var workbook = new Workbook();

            // Save the workbook in macro‑enabled format
            string outputPath = "output.xlsm";
            workbook.Save(outputPath, SaveFormat.Xlsm);
            Console.WriteLine($"Workbook saved to: {Path.GetFullPath(outputPath)}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
    }
}
